172.         if !frames.is_empty() {
173.             let reason: &str = "frames vector is not empty";
174.             error!("{reason}");
175.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
176.         }
177.         if frames.capacity() < count {
178.             let reason: &str = "frames vector has insufficient capacity";
179.             error!("{reason}");
180.             return Err(Error::new(ErrorCode::InvalidArgument, reason));
181.         }
