    proof! {
        lemma_manager_attached(self);
    }

    #[cfg_attr(verus_keep_ghost, verus_spec(
        invariant
            self@.wf(),
    ))]
    for _ in 0..count {
        match self.upool.alloc() {
            Ok(frame) => frames.push(frame),
            Err(error) => {
                frames.clear();
                proof! {
                    lemma_user_bulk_err_restored(self, g_old);
